package org.hancel.file

import android.content.Intent
import android.os.Bundle
import androidx.activity.OnBackPressedCallback
import androidx.activity.enableEdgeToEdge

/**
 * CrossFile mobile MainActivity — replaces the one generated by `tauri android init`.
 *
 * Three shell-level jobs live here (see docs/mobile.md §5/§6):
 *   1. keep a `dataSync` foreground service running so a backgrounded/locked
 *      transfer is not killed by the system;
 *   2. make the Android back gesture background the task instead of destroying
 *      the activity/WebView (which would abort the WebRTC transfer);
 *   3. hand ACTION_SEND shares to [ShareIntake] (skeleton, not wired to JS yet).
 */
class MainActivity : TauriActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        enableEdgeToEdge()
        super.onCreate(savedInstanceState)

        // 1) Foreground service: protects the process while the transfer runs.
        KeepAliveService.start(this)

        // 2) Back gesture / button: move the task to the background, keep the WebView.
        onBackPressedDispatcher.addCallback(this, object : OnBackPressedCallback(true) {
            override fun handleOnBackPressed() {
                moveTaskToBack(true)
            }
        })

        // 3) Share panel intake (copy to cache + marker; JS wiring is a TODO).
        ShareIntake.handleIntent(this, intent)
    }

    override fun onNewIntent(intent: Intent) {
        super.onNewIntent(intent)
        setIntent(intent)
        // Warm-start share (app already running): singleTask reuses this activity.
        ShareIntake.handleIntent(this, intent)
    }

    override fun onDestroy() {
        // Rotation also destroys the activity; only stop the service on a real finish.
        if (isFinishing) KeepAliveService.stop(this)
        super.onDestroy()
    }
}
